# Own-wording magic items of Griffon's Saddlebag Book 1 (2024), part B: Dragon's Call to Mammoth Boots. Row shape as tdcsr_item.py.
ITEMS = []; SP = {}; WPN = {}; GEAR = []
def add(name, typ, rar, att, text, **o):
    ITEMS.append((name, typ, rar, att, text, o))

_SUGAR = "**Upset Stomach.** Only one sugarbomb with this trait can affect you at a time. Eating a second one ends the first and forces a DC 13 Constitution save, or you are Poisoned for 1 minute."

add("Dragon's Call", "Wondrous Item", "Uncommon", 0, "An ear cuff that teaches you Draconic while you wear it. You also get +1 to Intelligence, Wisdom and Charisma checks about dragon lore.")
add("Dragon-Kindled Edge", "Weapon", "Legendary", 1, "A longsword made from an ancient dragon's remains. +3 to attack and damage rolls, +2d6 damage against Dragons, and you know Draconic.\n**Kindled Cleave.** Reaction when a hostile dragon's breath affects you: the blade splits it, sparing you and everything in a 30 ft Cone behind you. Once per dawn. If the breath dealt damage, the blade glows for 1 minute (Bright Light 10 ft, Dim 10 ft more) and the first hit you land with it deals an extra 6d6 of the breath's damage type, ignoring Resistance and Immunity.\n**Lesser Draconic Resistance.** Once per dawn, turn a failed save into a success if you failed by 4 or less.", fx={"atk": 3, "dmg": 3}, base=["Longsword"], ch=[1, "1", "dawn"])
add("Dream Mantle", "Wondrous Item", "Very Rare", 1, "A short purple cape that shows illusions of faraway places. Creatures more than 30 ft away have Disadvantage on sight-based Perception checks to spot you and on ranged attacks against you. This stops while you are Incapacitated, Restrained or unable to move. You can cast Dream (DC 16) from it over 1 minute, as the messenger. After that, wait 7 days.", ch=[1, "1", "7 days"])
add("Druidic Throwing Club", "Weapon", "Rare", 1, "A club with the Thrown property (range 20/60). +1 to attack and damage rolls. You know Shillelagh, and the spell does not end when you throw the club. After a ranged attack with it, the club flies back to your hand.", fx={"atk": 1, "dmg": 1}, base=["Club"], by="Druid or Ranger")
add("Dryadleaf", "Wondrous Item", "Common", 0, "A plant with up to four leaves that sways as if in a breeze. As a Magic action, eat a mature leaf to speak with Beasts, Plant creatures and nonmagical plants for 1 minute. A picked leaf lasts 7 days. Potting it needs a DC 15 Intelligence (Nature) or Wisdom (Survival) check or the plant dies. It regrows 1d4 leaves every 7 days with light watering and sun.")
add("Eaglereign", "Wondrous Item", "Uncommon", 1, "A feathered glove. As a Magic action, cast Find Familiar from it with an Eagle form. Once per dawn.\n**Summon Giant Eagle.** Focus for 1 hour to call a Giant Eagle within 30 ft. It is your ally, acts right after you, obeys verbal commands, and carries 480 lb at 8 miles per hour. It stays 12 hours or until it drops to 0 Hit Points or you dismiss it. It can fly 9 hours per summoning, resting 1 hour per 3 hours aloft. Once it is gone, wait 2 days.", ch=[1, "1", "dawn"])
add("Ear Cuff of the Vampire Bat", "Wondrous Item", "Uncommon", 1, "A ceramic bat ear cuff. When you fail a hearing-based Wisdom (Perception) check, you can command it (no action) to bite you. You take 1d4 + 1 Necrotic damage, which ignores Resistance and Immunity, and add that damage to the check.")
add("Edible Book of Recipes", "Wondrous Item", "Very Rare", 0, "A recipe book that turns its pages into food. Writing a simple recipe takes 1 minute, and eating the page as a Magic action feeds you like a meal. A complex recipe takes 10 minutes to write and feeds a creature for a day. It also raises Hit Point maximum and current Hit Points by 1d10 + Proficiency Bonus until a Long Rest and lets a Poisoned or diseased eater repeat the save (once per 24 hours per creature). It works as a Spellcasting Focus for Create Food and Water.\nThe book holds 50 pages. Removing the last page or rebinding it requires a d20 roll. On a 1 the book burns into a Heroes' Feast and a 60 ft wine-and-cooking smell lasting 30 days. Otherwise rebind it with fine paper costing 5 gp per page.")
add("Eldritch Scarf", "Wondrous Item", "Rare", 0, "A wrinkled scarf with an extradimensional space (60 lb, 6 cubic feet) reachable only while worn. It always weighs 1 lb. Retrieving an item takes a Bonus Action, and its frayed hands carry up to 10 lb. Ironing it flat spills the contents. Living creatures cannot be stored. If destroyed, the contents are lost.\nAs a Magic action, use its hands for a simple task within 5 ft. They cannot attack or activate magic items. Putting it in a Bag of Holding, Portable Hole or similar item destroys both and opens a gate to the Astral Plane. Creatures within 10 ft not behind Cover are pulled through. The gate is one way and then closes.")
add("Enchantment Breaker", "Ring", "Rare", 0, "A ring with slowly turning chains. When healing magic such as Cure Wounds affects you, use a Reaction to repeat a save against an Enchantment spell affecting you.\n**Shatter Enchantment.** When you fail a save against an Enchantment spell, use a Reaction so you and allies within 10 ft that were targeted can reroll. Then wait 1d4 days.", ch=[1, "1", "1d4 days"])
add("Essence of Rage", "Potion", "Rare", 0, "Drinking it starts a 1-minute rage as the level 1 Barbarian feature, even in Heavy armor. The rage ends early if you are Incapacitated. If your turn ends without you attacking an enemy, forcing a save, or using a Bonus Action to extend it, you take 1d4 Psychic damage and the rage continues another round.")
add("Ether Spear", "Weapon", "Very Rare", 1, "A spear with the Thrown property (20/60). +2 to attack and damage rolls and it deals Force damage. When you take the Attack action, pick a space you can see within 20 ft. The tip appears there and you can make melee attacks against a target within 5 ft of that space this turn. These attacks ignore Cover.\n**Ethereal Sight.** Bonus Action: see 60 ft into the Ethereal Plane for 1 minute. Once per dawn.", fx={"atk": 2, "dmg": 2}, base=["Spear"], ch=[1, "1", "dawn"])
add("Everice Box", "Wondrous Item", "Uncommon", 0, "A 25 lb wooden box (3 ft by 2 ft by 2 ft) that keeps its contents at 40 degrees Fahrenheit and holds 24 Rations. A trapped creature is freed by a DC 10 Strength (Athletics) check from itself or someone within 5 ft. With the lid closed and latched, a Magic action and command word shrinks it to 1 ft by 8 in and halves the weight. Opening the latch restores full size. Living creatures cannot be shrunk this way.")
add("Everlasting Sugarbomb", "Wondrous Item", "Common", 0, "A 2-inch candy that changes flavor as it dissolves. After 1 minute of dissolving, it feeds a creature for a day. It has 30 uses before it is gone. Biting to its center needs a DC 25 Strength or Constitution check, and success leads to a DC 16 Constitution save or Poisoned for 1 minute.", ch=[30, "0", "none"])
add("Eye of Dendallen", "Wondrous Item", "Rare", 1, "Cast See Invisibility from it at will. You gain Darkvision 60 ft (or +30 ft if you had it). Bonus Action: see through magical Darkness for 1 minute, once per dusk.\n**Curse.** On attuning, make a DC 20 Wisdom save. On a success, you can end attunement at once. On a failure, or if you keep it, you tear out an eye for 4d10 Necrotic damage (none if already missing one) and the Eye takes the socket until Remove Curse. If attunement ends, it escapes as a Spider with the Undead type and 5 Hit Points. Killing it unattuned destroys it.\n**Dendallen Familiar.** Magic action: the eye crawls out and acts like a Find Familiar summon. At 0 Hit Points or when dismissed it returns, and at 0 its powers stop until dusk.", ch=[1, "1", "dusk"])
add("Eye of the Bookwurm", "Wondrous Item", "Uncommon", 0, "A glass sphere that finds words in writing. Bonus Action with a command word: speak a word or phrase and it floats in the sphere. Holding the eye highlights that text in green wherever you look. After the first use you can change the phrase freely for 1 hour. Then wait until dawn.", ch=[1, "1", "dawn"])
add("Fable's End", "Weapon", "Very Rare", 1, "A mace. +1 to attack and damage rolls. When you roll a natural 20 against a Large or smaller creature, it makes a DC 15 Charisma save or is banished to a harmless demiplane until the end of its next turn. Against a Fey, a roll of 19 or 20 is a Critical Hit and forces the save, and the Fey has Disadvantage on it.", fx={"atk": 1, "dmg": 1}, base=["Mace"])
add("Ferryman's Take", "Wondrous Item", "Rare", 0, "Two copper coins, heads and tails. As a Magic action, place them on the eyes of a dead, willing or Unconscious Humanoid. They do nothing unless both face the same way.\n**Heads.** An Unconscious creature becomes Stable. A conscious one enters a death-like state for 1 hour, with Immunity to Psychic damage (once per 24 hours).\n**Tails.** A dead creature gains Gentle Repose. Its body cannot be found by magic and its soul cannot be contacted.")
add("Festerwood Buckler", "Armor", "Uncommon", 0, "A shield with glowing amber pustules that shed Bright Light 5 ft and Dim Light 5 ft more. When a creature you can see within 5 ft misses you, use a Reaction to bash it. It makes a DC 13 Dexterity save or takes 1d4 + 1 Acid damage.", base=["Shield"])
add("Festerwood Claymore", "Weapon", "Rare", 0, "A greatsword of hard festerwood with beetles inside. +1 to attack and damage rolls. On a natural 20, beetles swarm the target for 1d4 turns, dealing 1d6 Piercing at the start of each of its turns and halving its Speed. The target or a creature within 5 ft can use an action to swat them away. Against plants, Plant creatures and wooden objects the damage is maximized and lasts 4 turns.", fx={"atk": 1, "dmg": 1}, base=["Greatsword"])
add("Festerwood Fungal Stave", "Staff", "Very Rare", 1, "A fungal staff with 25 charges that regains 1d10 + 15 at dusk. It needs a Cleric, Druid or Sorcerer. Magic action, spend any charges to raise that many mushroom patches within 60 ft. They are Difficult Terrain and deal 2d4 Poison per 5 ft moved. They last 1 minute or until dismissed with a Bonus Action.\nBonus Action, using your spell save DC: Fog Cloud (1), Stinking Cloud (3), Cloudkill (5) or Insect Plague (5). The spell needs no Concentration, ends at the end of your next turn and must target a point next to your mushrooms. Spending the last charge, roll d20. On a 1 the staff is destroyed and a hostile Violet Fungus grows.", base=["Quarterstaff"], ch=[25, "1d10+15", "dusk"], by="Cleric, Druid, or Sorcerer")
add("Festerwood Logger", "Weapon", "Uncommon", 0, "A hardened festerwood handaxe. Hits deal an extra 1d4 Acid damage, maximized against plants, Plant creatures and wooden objects.", base=["Handaxe"])
add("Festerwood Vizard", "Wondrous Item", "Rare", 1, "An insect-like wooden mask that fits your face. You have Blindsight 10 ft. As a Magic action, beetles pour out as a Swarm of Insects (Fly Speed) that you command, moving and attacking on summoning and then as a Bonus Action each turn. If you are Incapacitated, it takes the Dodge action. It vanishes at 0 Hit Points or after 10 minutes without attacking. Once per dusk.", ch=[1, "1", "dusk"])
add("Festerwood's Light", "Weapon", "Legendary", 1, "A rapier inlaid with Lightspore scrapings. +1 to attack and damage rolls. You have Advantage on checks to find places in the Festerwood and Immunity to magical contagions. It sheds Bright Light 10 ft and Dim Light 10 ft more.\nMagic action with a command word: spores hit all other creatures within 30 ft. An ally can use a Reaction to attack or move up to half Speed without Opportunity Attacks. An enemy makes a DC 17 Constitution save or is Incapacitated until the end of your next turn. Once per dusk.\n**Charges.** 5 charges, regains 1d3 + 2 at dusk. Spend 1 to cast Charm Person (level 4), Compulsion, Confusion, Contagion, Faerie Fire, Locate Animals or Plants or Moonbeam (level 4), with save DC 17 and +9 to hit. You can also cast Dancing Lights. Spend 1 charge to remove a Spore Counter from a willing creature you touch.", fx={"atk": 1, "dmg": 1}, base=["Rapier"], ch=[5, "1d3+2", "dusk"])
add("Fife of Dragonsong", "Weapon", "Rare", 1, "A fife that is also a blowgun, for Bards. You are proficient with it as an instrument and as a Blowgun. +1 to attack and damage rolls and +1d6 Thunder damage on a hit.\n**Dragonsong.** Magic action, spend a Bardic Inspiration use. Enemies in a 15 ft Cone make a DC 15 Constitution save or take 2d6 Thunder damage and are pushed 10 ft (half damage on a success). Allies in the Cone who hear it gain 2d6 Temporary Hit Points and +10 ft Speed until the end of their next turn.", fx={"atk": 1, "dmg": 1}, base=["Blowgun"], xd=["+1d6 Thunder"], by="Bard")
add("Fire Dervish Cloak", "Wondrous Item", "Rare", 1, "A crackling cloak with 5 charges that regains all at dawn. Once per turn, spend 1, 2 or 3 charges (no action) and lower your Speed by 10, 20 or 30 ft until the end of the turn to spin. Creatures within 5 ft make a DC 15 Dexterity save. On a failure they take 1d8 Fire per charge spent and cannot make Opportunity Attacks against you this turn.", ch=[5, "all", "dawn"])
add("Fire Fire!", "Weapon", "Rare", 1, "A kobold-made light crossbow with 3 charges that regains 1d3 at dawn. While it has a charge it sheds Bright Light 20 ft and Dim Light 20 ft more, and nonmagical Bolts it fires deal an extra 1d6 Fire. Magic action, spend 1 charge: a 30 ft Cone, DC 15 Dexterity save, 4d6 Fire on a failure and half on a success, and loose flammables ignite. Spending the last charge, roll d20. On a 1 the weapon turns nonmagical.", base=["Light Crossbow"], xd=["Bolts: +1d6 Fire"], ch=[3, "1d3", "dawn"])
add("Fire Wand of the Unbroken Circle", "Wand", "Rare", 1, "An ash wand for Druids with 7 charges that regains 1d6 + 1 at dawn. Cast Flame Blade (2 charges) or Produce Flame (0 charges, or 1 at level 5) with +5 to hit. Flame Blade burns above the wand instead of in your hand. If you would fail a Constitution save to keep Concentration on it, spend 1 charge as a Reaction to succeed. Spending the last charge, roll d20. On a 1 the wand burns to ash.", ch=[7, "1d6+1", "dawn"], by="Druid")
add("Firecracker Crystals", "Wondrous Item", "Common", 0, "A bag of 1d4 + 8 festival crystals. As a Magic action, throw one at a solid surface within 20 ft to release a harmless sensory effect that ends at the end of your turn. Roll 1d8 for each crystal for its color: 1 flame, 2 flash and citrus scent, 3 fizzing motes, 4 foul-sweet green smoke, 5 big bubbles, 6 a snippet of music, 7 glitter, 8 a mystery effect (roll again, rerolling 8s). All effects have a 5 ft reach.")
add("Fireweaver Gloves", "Wondrous Item", "Uncommon", 1, "Golden gloves that let you cast Produce Flame (+5 to hit) with a 1-hour duration. You can shape that flame or other small nonmagical flames like clay for 1 minute, and a carried nonmagical flame burns for 1 hour. You can set the spell's flame down harmlessly for 1 minute (no action) and pick it up with a Magic action within 5 ft. When you take Fire damage with a free hand, use a Reaction to reduce it by 1d8 + 2.")
add("Flesh of Dendallen", "Wondrous Item", "Very Rare", 1, "A shirt of stitched flesh with 6 charges that regains 1d4 + 2 at dusk. Bonus Action, spend 1 charge: cast False Life. While Bloodied you regain 1d4 + Constitution modifier (minimum 1) Hit Points at the start of each turn, unless Unconscious or you took Fire or Radiant damage since your last turn began.\n**Curse.** When first worn, make a DC 20 Strength save. On a success, you can take it off. On a failure, it fuses to you and cannot be removed without Remove Curse. Nonmagical clothing beneath it is destroyed. You count as Undead as well and are Vulnerable to Radiant damage. Removing it deals 4d10 Necrotic damage.", ch=[6, "1d4+2", "dusk"])
add("Force Gauntlet", "Wondrous Item", "Rare", 1, "A jeweled gauntlet with 5 charges that regains 1d4 + 1 at dawn. When you hit with a melee attack from the gauntlet hand (weapon or Unarmed Strike), spend 1 charge for an extra 2d6 Force damage and a DC 15 Strength save. On a failure the target is pushed 10 ft away from you. On a success you are pushed 10 ft away from it. Targets two or more sizes larger than you pass automatically.", ch=[5, "1d4+1", "dawn"])
add("Fortune's Fivepence", "Wondrous Item", "Uncommon", 1, "An electrum coin you can spend like an Electrum Piece. Bonus Action with a command word, within 30 ft: call it to your hand or pocket.\n**Fate Flip.** 2 charges. Once per 24 hours flip it to try to refill: heads restores all, tails none. When you carry it and a D20 Test total is 10 or lower, spend 1 charge (no action), flip a coin, and add 1d10 on heads or subtract 1d10 on tails. It does not work if the result would be 0 or lower.", ch=[2, "all on heads", "24 hours"])
add("Fourarm Bracers", "Wondrous Item", "Very Rare", 1, "Bracers with 5 charges that regain 1d4 + 1 at dawn. Magic action: two spectral arms appear under your own for 1 minute. They handle objects, open doors and containers, and each carries 10 lb. Bonus Action with a command word, spend 1 charge: make two Unarmed Strikes with them using +3 Strength, your Proficiency Bonus, and 1d4 Force damage. Or spend 1 charge when summoning to double the carrying weight and make the duration 5 minutes.", ch=[5, "1d4+1", "dawn"])
add("Fragment of Elder Starlight", "Wondrous Item", "Very Rare", 0, "A 3 lb egg-shaped crystal shedding sunlight in Bright Light 20 ft and Dim Light 20 ft more. A Bonus Action touch adjusts or snuffs the light. Magic action with a command word: a 60 ft Emanation of light. Undead and Fiends there not behind Cover make a DC 16 Constitution save or take 8d6 Radiant and become Blinded until the end of your next turn (half damage on a success). Chosen living allies regain 4d6 Hit Points. Once per dawn. After that, its light drops to 10 ft Bright and 10 ft Dim until then.", ch=[1, "1", "dawn"])
add("Frefil's Jolly Oozebean Sugarbombs", "Wondrous Item", "Uncommon", 0, "A pack of 4 candies, with colors from 4d8 rolled when opened. Eating one is a Bonus Action and its effect lasts 1 minute. 1 White: breathe underwater. 2 Black: Resistance to Acid and can eat inedible, nonpoisonous organics. 3 Blue: grapple partners take 1d8 Acid. 4 Gray: Advantage on saves against Charmed and Frightened. 5 Gold: Climb Speed equal to your Speed. 6 Red: 1d8 + 4 Temporary Hit Points. 7 Green: Resistance to Poison and Advantage on checks to end Grappled or Restrained. 8 Yellow: Resistance to Lightning and Immunity to Magic Missile damage.\n" + _SUGAR)
add("Frefil's Tiny Tasty Tongue Twisty Sugarbombs", "Wondrous Item", "Uncommon", 0, "A bag of 12 gumballs. As a Magic action, chew one for 5 minutes. You understand the literal meaning of any language you hear or see signed, and your accent matches the speaker's.\n" + _SUGAR)
add("Frost Giant Fork", "Weapon", "Rare", 1, "A giant's table trident with the Thrown property (20/60). +1 to attack and damage rolls. After a melee hit, make a Bonus Action bite against the same target using Strength and Proficiency Bonus, dealing 1d6 Piercing.\n**Curse.** While attuned you must eat twice the normal amount of food and gain 1 Exhaustion level if a day passes without enough.", fx={"atk": 1, "dmg": 1}, base=["Trident"])
add("Frostbitten Buckler", "Armor", "Uncommon", 1, "An icy shield with 3 charges that regains all at dawn. When a creature you can see hits you in melee, spend 1 charge as a Reaction to deal 2d4 Cold damage to it. After the attack you gain Temporary Hit Points equal to the damage dealt.", base=["Shield"], ch=[3, "all", "dawn"])
add("Frozen Dagger", "Weapon", "Uncommon", 1, "A dagger that deals Cold damage instead of Piercing. On a natural 20, the target makes a DC 12 Constitution save or is Paralyzed until the end of its next turn. On a success its Speed is halved until then, unless it is immune to Paralyzed.", base=["Dagger"])
add("Funeral Marchers", "Wondrous Item", "Uncommon", 0, "Black leather boots. When you drop to 0 Hit Points and gain Unconscious, you can choose not to fall Prone. While Unconscious and standing this way, you can walk up to 10 ft on your turn after making a Death Saving Throw.")
add("Galea of the Soulfire Phoenix", "Wondrous Item", "Artifact", 1, "A helmet of the phoenix hero Fara, with 7 charges that regain 1d4 + 3 at dawn. You have Resistance to Fire, and in combat harmless flames shed Bright Light 20 ft and Dim Light 20 ft more. If you die while attuned, it vanishes to the Elemental Plane of Fire.\n**Fiery Spirit.** You and allies in its Bright Light have Advantage on saves against Charmed and Frightened, and a 19 or 20 on a Death Saving Throw restores 1 Hit Point.\n**Ignite.** Bonus Action: cast Fire Shield (warm shield only) and gain flaming wings with a Fly Speed of 30 ft for the duration. Once per dawn.\n**Call of the Phoenix.** Spend charges (save DC 18) to cast Healing Word at level 2 (1), Death Ward (3) or Flame Strike (4).\n**From the Ashes.** Reaction when reduced to 0 Hit Points but not killed: drop to 1 instead, regain 14 Hit Points, and creatures within 10 ft make a DC 18 Dexterity save or take 4d10 Fire (half on a success). Wings carry you up to 60 ft away without Opportunity Attacks. Then wait 2 days.\nIt has random Artifact properties. Only an ancient phoenix eating it destroys it, and the phoenix is reborn.", fx={"res": ["Fire"]}, ch=[7, "1d4+3", "dawn"])
add("Galvanic Steelsnare", "Wondrous Item", "Rare", 0, "A steel chain Net with the Heavy property. A creature Restrained by it makes only one attack per turn. While a target within 30 ft of you is Restrained by it, use a Bonus Action and command word to shock it for 1d6 Lightning damage, or 2d6 against metal creatures or metal armor. Usable once per turn start. Escape needs an action and a DC 15 Strength (Athletics) check by the target or a creature within 5 ft (Disadvantage for Small or smaller). Destroying the Net (AC 12, 15 HP, Resistance to Slashing, Immunity to other damage) also frees it. It repairs itself in 1d6 + 1 days.")
add("Gibberbox", "Wondrous Item", "Rare", 0, "A 7 lb enamel and bone box (1 ft by 6 in by 6 in) holding the paste of a gibbering mouther. Magic action to open: a toothy mouth babbles, and touching it deals 1d6 Piercing. Each creature starting its turn within 20 ft that can hear makes a DC 10 Wisdom save. On a failure it cannot make Opportunity Attacks until its next turn and rolls d8: 1-4 does nothing, 5-6 uses all movement in a random direction with no action, 7-8 makes a melee attack on a random creature in reach. Lasts 1 minute or until closed with a Magic action. Then wait 24 hours. The paste cannot be removed.", ch=[1, "1", "24 hours"])
add("Give and Take", "Weapon", "Very Rare", 1, "Two scimitars joined by a chain, Give (mithral) and Take (obsidian). Your extra attack from the Light property can add your ability modifier to its damage. They share 10 charges and regain 1d6 + 4 at midday. When you hit with a blade, you can spend 1 charge for its effect.\n**Give.** You and every other creature within 5 ft of the target gain 2d6 Temporary Hit Points.\n**Take.** The target takes 2d6 Necrotic damage and you and other creatures within 5 ft of it take half as much.", base=["Scimitar"], ch=[10, "1d6+4", "midday"])
add("Glove of the Aegis", "Wondrous Item", "Rare", 1, "A glove with 5 charges that regains 1d3 + 2 at dawn. When a target you can see hits you with an attack roll, use a Reaction and spend any number of charges to gain +2 AC per charge against that attack. It does not work while you wield a Shield.", ch=[5, "1d3+2", "dawn"])
add("Glove of the Grim Fandango", "Wondrous Item", "Rare", 1, "A glove for Bards. Worn on your dominant hand, you are proficient with all Musical Instruments. After playing for 1 minute, illusory spectral musicians join you and fade 1 minute after you stop. With them you have Advantage on Charisma (Performance) checks and +2 to your spell save DC for Enchantment spells on targets who can hear you.", by="Bard")
add("Grass Carpet", "Wondrous Item", "Common", 0, "A fertile turf roll 10 ft by 5 ft with 1 inch of soil, weighing 30 lb. Plants need half the usual sun and water, and each inch of soil counts as a foot of normal soil. Folding or stacking carpets deepens the soil. It rolls up or out in 1 minute to 1 ft across. A magical blade can cut it into plots at least 1 ft on each side.")
add("Grass Whistle Blade", "Weapon", "Very Rare", 1, "A dagger whose blade is enchanted grass with a lulling tone. +2 to attack and damage rolls. It has 4 charges and regains 1d4 at dawn. On a melee hit you can forgo the damage and spend 1 charge. The target makes a DC 16 Wisdom save or is Incapacitated until the end of its next turn, then saves again. A second failure means Unconscious for 1 minute, which ends on damage or when someone within 5 ft shakes it awake. A second success deals 3d8 Psychic damage. Creatures that do not sleep or are immune to Exhaustion automatically succeed.", fx={"atk": 2, "dmg": 2}, base=["Dagger"], ch=[4, "1d4", "dawn"])
add("Gravity Goblet", "Wondrous Item", "Common", 0, "A glass and silver goblet that makes liquid flow against gravity. Tilted to drink, it climbs up the cup and drops down at the rim. Swirling it makes the liquid flow the opposite way. Floating solids other than ice are unaffected.")
add("Greaves of Dendallen", "Wondrous Item", "Rare", 1, "Skeletal greaves. You have a Climb Speed equal to your Speed and can walk on liquid. Once per turn you can jump 30 ft for 10 ft of movement.\n**Curse.** When first worn, make a DC 20 Constitution save. On a success, you can take them off. On a failure, your legs break for 6d8 Necrotic damage that ignores Resistance and Immunity, and the greaves stay on until Remove Curse. The broken legs do not slow you while worn. Once removed, your Speed is 0 and rises by 5 ft every 24 hours until normal.")
add("Grip of Dendallen", "Wondrous Item", "Very Rare", 1, "Gloves of bone chain. Your Unarmed Strikes deal 1d6 Necrotic damage, maximized against plants and Plant creatures. Cast Blight (Touch range), Contagion or Vampiric Touch (save DC 16, +8 to hit). Each spell can be cast once, then not again until dusk.\n**Curse.** When first worn, make a DC 16 Wisdom save. On a success, you can take them off. On a failure, chains pierce your arms for 4d6 Piercing and the gloves stay on until Remove Curse. Your hands rot with an uncontainable stench, giving you Disadvantage on Charisma checks and 1d6 Necrotic damage right after a Long Rest restores all your Hit Points. After removal, the rot takes 1d4 days to heal.")
add("Halberd of the Peacock", "Weapon", "Rare", 1, "A mirror-polished halberd with five gems. +1 to attack and damage rolls. It has 5 charges and regains 1d4 + 1 at dawn. Spend 1 to cast Disguise Self or 2 to cast Alter Self, Mirror Image or Shatter (save DC 15).\n**Curse.** Attuning curses you. You refuse to part with it and have Disadvantage on attacks with other weapons. When you drop a creature to 0 Hit Points with it, make a DC 12 Wisdom save or admire yourself until your next turn, losing remaining movement, action, Bonus Action and Reaction. You automatically fail Dexterity saves while admiring.", fx={"atk": 1, "dmg": 1}, base=["Halberd"], ch=[5, "1d4+1", "dawn"])
add("Hand of the Master", "Wondrous Item", "Uncommon", 1, "A seamless satin glove that fits either hand and works as a missing hand or fingers. You can cast Mage Hand at will from it, with the hand appearing in the glove. This doubles the spell's duration and the weight it carries.")
add("Harp of Valor", "Weapon", "Very Rare", 1, "A 10-string shortbow for Bards that is also a harp and a Spellcasting Focus. You are proficient with the harp and have Advantage on Charisma (Performance) checks with it. +2 to attack and damage rolls, and Arrows deal Thunder damage. It has 10 charges and regains 1d6 + 4 at dawn. Spend up to 5 charges to cast Magic Missile or Thunderwave at a level equal to the charges, with your spell save DC.", fx={"atk": 2, "dmg": 2}, base=["Shortbow"], ch=[10, "1d6+4", "dawn"], by="Bard")
add("Hasty Sugarbomb", "Wondrous Item", "Uncommon", 0, "A sweet eaten as a Magic action to raise your Speed by 5 ft for 1 hour.\n" + _SUGAR)
add("Hat Trick", "Wondrous Item", "Uncommon", 0, "A purple hat with 3 charges that regains 1 at dawn. While holding it, spend 1 charge to cast Find Familiar as a Magic action, as a rabbit (Weasel stats) or dove (Owl stats). It lasts 1 minute and cannot deliver spells. While wearing it you can cast Prestidigitation using only the sensory effect or minor creation (illusory image) options.", ch=[3, "1", "dawn"])
add("Hcor'uk the Colossal's Portable Handheld Weapon of Walloping", "Weapon", "Very Rare", 1, "A flail made from a rope and a 200 lb boulder, with Heavy, Reach and Two-Handed. Hits deal an extra 1d8 Bludgeoning, or 2d8 against a structure. On a natural 20 against a Huge or smaller creature, it makes a DC 16 Strength save or falls Prone. The rope and boulder cannot be separated, and attuning makes lifting the boulder effortless.", base=["Flail"], xd=["+1d8 Bludgeoning (2d8 vs structures)"])
add("Heart of the Sleeveless", "Wondrous Item", "Common", 0, "A silky vest that flatters your build and sags when taken off. Its color follows your mood: Anger red, Anticipation orange, Joy yellow, Love lime green, Fear green, Sadness navy blue, Disappointment indigo, Disgust violet, Jealousy black, Surprise white. Unworn it is a muted blue.")
add("Hellfire Pitchfork", "Weapon", "Very Rare", 1, "A warm black iron trident weighing 10 lb with the Heavy property, so its throwing range is 15/45. +1 to attack and damage rolls and +1d8 Radiant damage on a hit. Bonus Action with a command word, while it is within 60 ft: it vanishes in smoke and appears in your open hand. If you do this right after a ranged attack, a 5 ft pillar of flame erupts in its space instead, and creatures there make a DC 16 Dexterity save or take 1d8 Fire.", fx={"atk": 1, "dmg": 1}, base=["Trident"], xd=["+1d8 Radiant"])
add("Helm of Heroes", "Wondrous Item", "Rare", 1, "A helmet that gives +1 AC while you wear no armor (a Shield is fine). Without armor, a natural 20 on an attack makes it glimmer for 1 minute. While it glimmers, you gain Temporary Hit Points equal to half your level (rounded down) at the start of each of your turns, and you and allies within 10 ft are Immune to Frightened.")
add("Helmsman's Shelter", "Armor", "Rare", 1, "A shield that gives +1 AC on top of its normal bonus, and +1 to checks to control a waterborne vehicle. It has 5 charges and regains all at dawn. Spend 3 charges to cast Control Water (save DC 15). Or Magic action, spend 1 charge to seize a water vehicle with a rudder within 300 ft. A creature steering it makes a DC 15 Strength save, and on a failure you turn the vehicle up to 90 degrees and keep control until your next turn.", fx={"ac": 1}, base=["Shield"], ch=[5, "all", "dawn"])
add("Hexaxe", "Weapon", "Uncommon", 1, "A handaxe for Warlocks. It gives +1 to attack and damage rolls against creatures under a Concentration spell you cast as a Warlock. It has 3 charges and regains all at dusk. When you must save to keep Concentration on a Warlock spell while holding it, spend 1 charge as a Reaction to add your Charisma modifier (minimum +1).", base=["Handaxe"], ch=[3, "all", "dusk"], by="Warlock")
add("Hurricane Lance", "Weapon", "Very Rare", 1, "A lance with +2 to attack and damage rolls. It has 4 charges and regains 1d4 at dawn. Magic action, spend 1 charge: surround yourself with wind for 1 minute, so you can Disengage as a Bonus Action. Spend a second charge (no action) to extend this to your mount. It ends if you are Unconscious or let go of the lance. You can also cast Thunderwave at level 3 (save DC 16) once per dawn.", fx={"atk": 2, "dmg": 2}, base=["Lance"], ch=[4, "1d4", "dawn"])
add("Ice Sickle", "Weapon", "Uncommon", 0, "A sickle from the Everglacier covered in regrowing icicles. The first target you hit on each of your turns takes an extra 1d6 Cold damage.", base=["Sickle"], xd=["First hit each turn: +1d6 Cold"])
add("Immovable Button", "Wondrous Item", "Common", 0, "An iron shirt button. Bonus Action with the command word \"hold\": it fixes onto unworn fabric or fabric worn by a willing creature, even against gravity. It supports 500 lb and stops tearing. More weight deactivates it. A Utilize action and DC 20 Strength (Athletics) check moves it up to 10 ft. A Study action and DC 10 Intelligence (Investigation) check shows it is magic. It holds 1 minute, and its magic is spent afterward.")
add("Infernal Aegis", "Armor", "Very Rare", 1, "A shield. Bonus Action with a command word: wreathe it in harmless flames (Bright Light 20 ft, Dim Light 20 ft more) until you repeat the word or let go. While holding it you have Resistance to Fire and +1 AC on top of its normal bonus. It has 4 charges and regains 1d4 at dawn. While ablaze, spend charges to cast Fire Shield (2, warm shield only) or Hellish Rebuke (1, save DC 16).", fx={"ac": 1, "res": ["Fire"]}, base=["Shield"], ch=[4, "1d4", "dawn"])
add("Inferno Rope", "Wondrous Item", "Uncommon", 0, "A 10 ft sulfur-smelling rope. Magic action with a command word: lay it in a line to make a 15 ft tall wall of fire along it for 1 minute (Bright Light 15 ft, Dim Light 15 ft more). Creatures other than you within 5 ft when it ignites make a DC 13 Dexterity save or take 2d4 Fire, and again on first entering the wall each turn or ending a turn in it. The rope returns afterward. Once per dawn. Only magic breaks it, and then it is a plain Rope.", ch=[1, "1", "dawn"])
add("Ionbreaker, the Tempest's Reach", "Weapon", "Artifact", 1, "A longbow forged in the Stormheart storm. +3 to attack and damage rolls.\n**A Storm Is Coming.** Add 1d10 to Initiative while it is on you.\n**Fast as Lightning.** After the Attack action, make one attack with it as a Bonus Action.\n**Discharge.** After a ranged hit on your turn, the target and creatures within 5 ft take 1d8 Lightning (once per creature per round).\n**Chained Conduits.** A ranged hit makes the target a conduit for 1 minute. Bonus Action with a command word: electrify all conduits within 60 ft. Lines 5 ft wide arc between conduits within 30 ft. Each conduit takes 2d8 Lightning, others in a Line make a DC 18 Dexterity save for 2d8 (half on a success), and each can be hit once per turn.\n**Maelstrom Marksman.** Once per turn, reroll a missed ranged attack against another target within 30 ft of the first, with Disadvantage.\n**Zephyr Step.** Fly Speed equal to Speed, hovering within 20 ft of the ground.\n**Embrace the Storm.** Each time you take Lightning damage while attuned, roll 1d8: 1 Vulnerable to Lightning until your next turn end, 2 thrown 20 ft and Prone, 3 Deafened 1 hour, 4 no Reactions 1 minute, 5 Fog Cloud within 5 ft for 1d4 rounds, 6 up to three creatures within 10 ft take 1d8 Lightning, 7 double Speed until your next turn end, 8 Immune to Lightning until your next turn end.\nIt has random Artifact properties and is destroyed only by lightning and an adamantine hammer in the Stormheart, releasing 10d10 Lightning and 10d10 Force within 60 ft.", fx={"atk": 3, "dmg": 3}, base=["Longbow"])
add("Ironleaf Maul of Entanglement", "Weapon", "Rare", 1, "A maul with a vine head. +1 to attack and damage rolls. It has 3 charges and regains 1d3 at dawn. After you hit a Medium or smaller target, spend 1 charge to force a Strength save (DC 8 + Strength modifier + Proficiency Bonus). On a failure it takes 1d6 Piercing and is Restrained until the end of its next turn.", fx={"atk": 1, "dmg": 1}, base=["Maul"], ch=[3, "1d3", "dawn"])
add("Ironleaf Oaken Shield", "Armor", "Uncommon", 1, "A reinforced wooden shield for Druids. +1 AC on top of its normal bonus. It reshapes onto you when you transform into a Beast, still giving +1 AC, and returns to your arm when you revert.", fx={"ac": 1}, base=["Shield"], by="Druid")
add("Ironleaf Plate", "Armor", "Very Rare", 1, "Plate armor lined with ironleaf vines. +1 AC, it does not impose Disadvantage on Stealth, and it gives you Resistance to Bludgeoning damage. Fire damage withers the vines for 1 minute, ending these benefits. You can cast Pass without Trace once per dawn.", fx={"ac": 1, "res": ["Bludgeoning"]}, base=["Plate Armor"], ch=[1, "1", "dawn"])
add("Ironshod Trotters", "Wondrous Item", "Uncommon", 1, "Boots with iron horseshoes. When you Dash, move 10 ft extra. Click them to cast Polymorph on yourself into a Riding Horse for 8 hours. You keep your Intelligence, Wisdom, Charisma and skill and save proficiencies. Carried bags become saddlebags but other gear melds in and is unusable. Damage taken in that form carries over to your normal form and ends the spell. Once per dawn.", ch=[1, "1", "dawn"])
add("Jotun's Jodhpurs", "Wondrous Item", "Rare", 0, "Riding pants. While you wear no Heavy armor and ride a non-Humanoid mount, you count as one size smaller.")
add("Killskull Longbow of Dread", "Weapon", "Rare", 1, "A longbow with a bear skull. It holds up to 4 charges and gains 1 each time you drop a Small or larger creature to 0 Hit Points with it. On a ranged hit, spend 1 charge for an extra 1d8 Psychic damage and a DC 15 Wisdom save. On a failure the target is Frightened for 1 minute, repeating the save at the end of each of its turns.", base=["Longbow"], ch=[4, "0", "never", "Gains 1 charge when you drop a Small or larger creature to 0 HP"])
add("Kindle Egg Sugarbomb", "Wondrous Item", "Uncommon", 0, "A spicy chocolate sweet eaten as a Magic action. For 1 hour you have Resistance to Fire and can endure temperatures down to -50 degrees Fahrenheit without protection.\n" + _SUGAR)
add("Knight's Standard of Valor", "Weapon", "Rare", 1, "A halberd with a flag. +1 to attack and damage rolls. You and allies within 10 ft add Proficiency Bonus to saves against or to end Frightened if not already proficient. An ally starting its turn within 10 ft gains +5 ft Speed until the turn ends. Changing the flag takes 1 hour of focus, possible during a Short Rest.", fx={"atk": 1, "dmg": 1}, base=["Halberd"])
add("Knight's Standard of Vigor", "Weapon", "Rare", 1, "A brass pike with a flag. +1 to attack and damage rolls. You and allies within 10 ft add Proficiency Bonus to saves against or to end Poisoned if not already proficient. When an ally gets Hit Points from a spell or potion in combat, use a Reaction to give it an extra 1d6 + 2. Changing the flag takes 1 hour of focus, possible during a Short Rest.", fx={"atk": 1, "dmg": 1}, base=["Pike"])
add("Knight's Standard of Virtue", "Weapon", "Rare", 1, "A decorated glaive with a flag. +1 to attack and damage rolls. You and allies within 10 ft add Proficiency Bonus to saves against or to end Charmed if not already proficient. When an ally you can see within 10 ft takes damage, use a Reaction to reduce it by 5 and take that much Force damage yourself. Changing the flag takes 1 hour of focus, possible during a Short Rest.", fx={"atk": 1, "dmg": 1}, base=["Glaive"])
add("Knocking Boots", "Wondrous Item", "Uncommon", 0, "Dwarven steel-toed boots with a key on the toe. Kick an object that is locked or otherwise sealed against entry to cast Knock on it. Once per dawn.", ch=[1, "1", "dawn"])
add("Kraken's Whip", "Weapon", "Uncommon", 0, "A whip made from a shrunken tentacle. Magic action: a Large or smaller creature you can see within 10 ft makes a DC 13 Strength or Dexterity save (its choice). On a failure it is Grappled and takes 1d4 + 2 Bludgeoning, and again at the end of each of its turns. Escape needs an action and a DC 13 Strength (Athletics) check by it or a creature within 5 ft. You cannot attack with the whip while grappling. You can end the grapple freely. Moving more than 10 ft away drags the target, costing you 1 extra foot per foot unless it is Tiny or two or more sizes smaller.", base=["Whip"])
add("Lance of the Hungering Dead", "Weapon", "Very Rare", 1, "A gruesome lance. The first time each turn you hit a living enemy in melee with it, it takes an extra 1d12 Necrotic damage and you gain Temporary Hit Points equal to half that damage (rounded up).", base=["Lance"], xd=["First hit each turn on a living target: +1d12 Necrotic"])
